import type { Database } from "bun:sqlite";
import { drizzle } from "drizzle-orm/bun-sqlite";
import { migrate as drizzleMigrate } from "drizzle-orm/bun-sqlite/migrator";

import * as schema from "./schema";

/**
 * Apply Drizzle migrations to a SQLite database. Migration SQL files live in
 * `packages/db/src/migrations/` and are generated by `bun run db:generate`
 * after editing `schema.ts`.
 *
 * The migrator is idempotent — already-applied migrations are skipped via the
 * `__drizzle_migrations` bookkeeping table it manages automatically.
 */
export function migrate(sqlite: Database, migrationsFolder: string) {
  const db = drizzle(sqlite, { schema });
  drizzleMigrate(db, { migrationsFolder });
}
